\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{pgfplotstable}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    title={粉红色主题数据图表},
    xlabel={X轴标签},
    ylabel={Y轴标签},
    xmin=0, xmax=10,
    ymin=0, ymax=100,
    xtick={0,2,4,6,8,10},
    ytick={0,20,40,60,80,100},
    legend pos=north west,
    grid=major,
    grid style={dashed, gray!30},
    width=12cm,
    height=8cm,
    % 粉红色主题设置
    axis background/.style={fill=pink!5},
    axis line style={pink!80!black},
    tick style={pink!80!black},
    title style={color=pink!70!red},
    xlabel style={color=pink!70!red},
    ylabel style={color=pink!70!red},
    legend style={fill=pink!10, draw=pink!50}
]

% 第一条曲线 - 深粉红色
\addplot [
    domain=0:10,
    samples=100,
    color=pink!80!red,
    thick
] {x^2};
\addlegendentry{二次函数 $y = x^2$}

% 第二条曲线 - 浅粉红色
\addplot [
    domain=0:10,
    samples=100,
    color=pink!50,
    thick,
    dashed
] {10*x};
\addlegendentry{线性函数 $y = 10x$}

% 散点数据点 - 使用不同的粉红色调
\addplot[
    only marks,
    mark=*,
    mark size=3pt,
    color=pink!60!purple,
    fill=pink!30
] coordinates {
    (1,1) (2,4) (3,9) (4,16) (5,25)
    (6,36) (7,49) (8,64) (9,81) (10,100)
};

\addlegendentry{数据点}

\end{axis}
\end{tikzpicture}

\end{document}
